1#include<iostream>
2using namespace std;
3
4class Board {
5    public:
6
7        char board[9] = { ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ' };
8
9        void print_board() {
10            cout << " " << board[0] << " | " << board[1] << " | " << board[2] << endl;
11            cout << "-----------" << endl;
12            cout << " " << board[3] << " | " << board[4] << " | " << board[5] << endl;
13            cout << "-----------" << endl;
14            cout << " " << board[6] << " | " << board[7] << " | " << board[8] << endl;
15        }
16
17
18        bool update_board(int position, char type) {
19
20            // if a player selects position n, n-1 index should be updated
21            // if the position is not already filled, update the board
22            if (board[position - 1] == ' ') {
23                board[position - 1] = type;
24                return true;
25            }
26
27            // if the position is already filled, ask user to select another position
28            else {
29                cout << "Position already selected. Select another position.";
30                return false;
31            }
32        }
33
34};
35
36class Player {
37    public:
38
39        string name;
40        char type;
41
42        // function to select the player type and name
43        void set_info(char type) {
44
45            // player type is 'X' if parameter is 'X' or 'x'            
46            if (type == 'X' || type == 'x') {
47
48                // set member variable to 'X'
49                this->type = 'X';
50
51                // get player name
52                cout << "Player selecting " << this->type << ", enter your name: ";
53                getline(cin, name);
54            }
55
56            // player type is 'O' if parameter is any other character 
57            else {
58                this->type = 'O';
59                cout << "Player selecting " << this->type << ", enter your name: ";
60                getline(cin, name);
61            }
62        }
63};
64
65class Game {   
66    public:
67
68        Board board;
69
70        Player player1;
71        Player player2;
72        Player* current_player;
73        
74        // constructor to set player data
75        Game() {
76            player1.set_info('X');
77            player2.set_info('O');
78            current_player = &player1;
79        }
80
81
82        void play() {
83            
84            int position;
85
86            // message to prompt player for their position
87            string message = "enter the position (1 - 9): ";
88
89            // using an infinite loop to run the game
90            // we will later add conditions to terminate the loop
91            while (true) {
92
93                cout << current_player->name << " " << message;
94                cin >> position;
95
96                // the update_board() function returns true if
97                // the user selected position is not already filled
98                bool update = board.update_board(position, current_player->type);
99
100                // update the board if the selected position is not filled
101                if (update) {
102
103                    board.print_board();
104
105                    // change current player when board is updated
106                    if (current_player == &player1) {
107                        current_player = &player2;
108                    }
109
110                    else {
111                        current_player = &player1;
112                    }
113                }
114            }
115        }
116
117};
